class Solution {
public:
    int miceAndCheese(vector<int>& reward1, vector<int>& reward2, int k) {
        int n = reward1.size();
        int total = 0;
        for (int i = 0; i < n; i++) {
            total += reward2[i];
        }
        vector<int> gains(n);
        for (int i = 0; i < n; i++) {
            gains[i] = reward1[i] - reward2[i];
        }
        nth_element(gains.begin(), gains.begin() + k, gains.end(), greater<int>());
        int gainSum = 0;
        for (int i = 0; i < k; i++) {
            gainSum += gains[i];
        }
        return total + gainSum;
    }
};
